<script setup lang="ts">
import { computed, ref } from 'vue'
import type { MatrixAccount } from '@/api/matrix'

const props = defineProps<{ account: MatrixAccount; loading?: boolean }>()
defineEmits<{ close: []; edit: []; manage: []; refresh: []; dashboard: []; polish: [] }>()
const profile = computed<Record<string, any>>(() => props.account.profile || {})
const runtime = computed<Record<string, any>>(() => props.account.runtimeProfile || {})
const datasets = computed<Record<string, any>>(() => props.account.datasetEvidence || {})
const risks = computed<Array<Record<string, any>>>(() => props.account.risks || [])
const activeRisks = computed(() => risks.value.filter(item => !['RESOLVED', 'EXPIRED', 'CLOSED'].includes(String(item.riskStatus))))
const severeRisks = computed(() => activeRisks.value.filter(item => ['CRITICAL', 'HIGH'].includes(String(item.severity))))
const riskFilter = ref<'ALL' | 'ACTIVE' | 'APPEALING' | 'RESOLVED'>('ALL')
const filteredRisks = computed(() => risks.value.filter(item => {
  const status = String(item.riskStatus || '')
  if (riskFilter.value === 'ACTIVE') return !['RESOLVED', 'EXPIRED', 'CLOSED'].includes(status)
  if (riskFilter.value === 'APPEALING') return status === 'APPEALING'
  if (riskFilter.value === 'RESOLVED') return ['RESOLVED', 'EXPIRED', 'CLOSED'].includes(status)
  return true
}))
const statusLabel = (v?: string) => ({ CONNECTED: '在线', DEGRADED: '连接波动', EXPIRED: '已过期', DISCONNECTED: '离线', UNKNOWN: '待检测', AUTHORIZED: '已授权', NOT_APPLICABLE: '无需授权', REVOKED: '已撤销', FULL: '完整', PARTIAL: '部分', UNSYNCED: '未同步', ACTIVE: '已启用', DISABLED: '已停用', SUCCESS: '成功', FAILED: '失败', CRITICAL: '严重', HIGH: '高风险', WARNING: '警告', INFO: '提醒', OPEN: '生效中', APPEALING: '申诉中', RESOLVED: '已处理' }[v || ''] || v || '未知')
const tone = (v?: string) => ['CONNECTED', 'AUTHORIZED', 'FULL', 'RESOLVED', 'ACTIVE', 'SUCCESS'].includes(v || '') ? 'good' : ['CRITICAL', 'HIGH', 'EXPIRED', 'DISCONNECTED', 'REVOKED', 'FAILED'].includes(v || '') ? 'bad' : ['DEGRADED', 'WARNING', 'PARTIAL', 'OPEN'].includes(v || '') ? 'warn' : 'muted'
const value = (v: unknown) => v === null || v === undefined || v === '' ? '—' : String(v)
const percent = (v: unknown) => {
  if (v === null || v === undefined || v === '') return '—'
  const number = Number(v)
  if (!Number.isFinite(number)) return String(v)
  return `${(number <= 1 ? number * 100 : number).toFixed(1).replace(/\.0$/, '')}%`
}
const time = (v?: string) => v ? new Date(v).toLocaleString('zh-CN', { hour12: false }) : '未同步'
const sourceLabel = (v?: unknown) => ({
  LOCAL_RUNTIME: '运行时实测',
  SYSTEM_DERIVED: '系统推导',
  PLATFORM_API: '平台接口',
  PLATFORM_WEB: '平台页面',
  MANUAL_IMPORT: '人工导入',
}[String(v || '')] || String(v || '来源未记录'))
</script>

<template>
  <div class="account-profile-backdrop" @click.self="$emit('close')">
    <section class="account-profile-modal" role="dialog" aria-modal="true" aria-labelledby="account-profile-title" tabindex="-1">
      <header class="account-profile__header">
        <div class="account-profile__identity"><div class="account-profile__avatar">{{ (account.shopNickname || account.accountNote || '闲').slice(0, 1) }}</div><div><div class="account-profile__title"><h2 id="account-profile-title">{{ account.accountNote || account.shopNickname || `账号 ${account.accountId}` }}</h2><span v-if="profile.shopLevel" class="badge badge--yellow">{{ profile.shopLevel }}</span><span class="badge badge--good">{{ statusLabel(account.authorizationStatus) }}</span></div><p>店铺 ID {{ account.accountId }} <i></i> {{ account.unb || '账号标识未同步' }} <i></i> {{ value(profile.region) }} <i></i> <b :class="tone(account.connectionStatus)">● {{ statusLabel(account.connectionStatus) }}</b></p></div></div>
        <div class="account-profile__header-actions"><div class="account-profile__live"><span>● 会话 {{ statusLabel(account.connectionStatus) }}</span><span>● 授权 {{ statusLabel(account.authorizationStatus) }}</span></div><button class="workbench__btn" @click="$emit('dashboard')">数据看板</button><button class="workbench__btn" title="进入当前店铺在售商品的擦亮预检，不会直接执行" @click="$emit('polish')">全店擦亮</button><button class="workbench__btn" :disabled="loading" @click="$emit('refresh')">↻ 刷新店铺详情</button><button class="account-profile__close" aria-label="关闭店铺详情" @click="$emit('close')">×</button></div>
      </header>
      <div class="account-profile__body" :aria-busy="loading">
        <div class="account-profile__left">
          <section class="profile-card level-card"><header><strong>鱼小铺等级</strong><small>店铺画像</small></header><div class="level-card__row"><span class="badge badge--yellow">{{ value(profile.shopLevel) }}</span><b>{{ value(profile.shopScore) }}</b><small>店铺分</small></div><div class="level-card__bar"><i :style="{ width: `${Math.min(100, Number(profile.shopScore || 0))}%` }"></i></div><div class="level-card__labels"><span>能力标签</span><div><em v-if="profile.superSeller">超级卖家</em><em>{{ value(profile.sellerCredit || profile.creditLevel) }}</em><em>{{ value(profile.buyerCredit) }}</em></div></div></section>
          <section class="profile-card"><header><strong>店铺指标</strong><small>{{ statusLabel(account.profileCoverageStatus) }}</small></header><div class="profile-metrics"><span>在售<strong>{{ value(profile.onSaleCount) }}</strong></span><span>粉丝<strong>{{ value(profile.followerCount) }}</strong></span><span>好评率<strong>{{ percent(profile.positiveRate) }}</strong></span><span>店铺分<strong>{{ value(profile.shopScore) }}</strong></span></div></section>
          <section class="profile-card portrait-card"><header><strong>信用画像</strong><small>来源 {{ account.profileSource || '未同步' }}</small></header><dl><div><dt>卖家信用</dt><dd>{{ value(profile.sellerCredit) }}</dd></div><div><dt>买家信用</dt><dd>{{ value(profile.buyerCredit) }}</dd></div><div><dt>实名认证</dt><dd>{{ value(profile.realNameVerified) }}</dd></div><div><dt>芝麻认证</dt><dd>{{ value(profile.zhimaVerified) }}</dd></div><div><dt>累计卖出</dt><dd>{{ value(profile.soldCount) }}</dd></div><div><dt>累计评价</dt><dd>{{ value(profile.ratingCount) }}</dd></div></dl><p>画像更新于 {{ time(account.profileSyncedAt) }}；“—”表示未同步，不代表 0。</p></section>
          <section class="profile-card"><header><strong>接入通道</strong><small>{{ account.accessChannels?.length || 0 }} 条证据</small></header><div v-if="account.accessChannels?.length" class="profile-channels"><article v-for="(channel, index) in account.accessChannels" :key="index"><div><strong>{{ channel.channelName || channel.channelCode }}</strong><span :class="['badge', `badge--${tone(String(channel.connectionStatus))}`]">{{ statusLabel(String(channel.connectionStatus)) }}</span></div><p>{{ channel.authorizationScope || '授权范围未记录' }}</p><small>来源 {{ sourceLabel(channel.source) }} · 核验于 {{ time(String(channel.lastCheckedTime || '')) }} · 最近成功 {{ time(String(channel.lastSuccessTime || '')) }}</small><em v-if="channel.lastErrorMessage">{{ channel.lastErrorMessage }}</em></article></div><p v-else class="profile-empty">接入通道证据尚未同步。</p></section>
          <section class="profile-card"><header><strong>账号运行档案</strong><span :class="['badge', runtime.isolationStatus === 'ISOLATED' ? 'badge--good' : runtime.isolationStatus === 'CONFLICT' ? 'badge--bad' : 'badge--muted']">{{ runtime.isolationStatus === 'ISOLATED' ? '隔离正常' : runtime.isolationStatus === 'CONFLICT' ? '发现冲突' : '隔离待检测' }}</span></header><dl class="runtime-profile"><div class="runtime-profile__identity"><dt>浏览器档案 ID</dt><dd>{{ value(runtime.browserProfileId) }}</dd></div><div><dt>存储范围</dt><dd>{{ runtime.storageScope === 'ACCOUNT' ? '每账号独立' : '—' }}</dd></div><div><dt>隔离档案</dt><dd>{{ value(runtime.profileType) }}</dd></div><div><dt>运行平台</dt><dd>{{ value(runtime.platform) }}</dd></div><div><dt>视口</dt><dd>{{ value(runtime.viewport) }}</dd></div><div><dt>时区</dt><dd>{{ value(runtime.timezoneId) }}</dd></div><div><dt>浏览器状态</dt><dd>{{ runtime.browserStateReady ? '已隔离保存' : '尚未就绪' }}</dd></div><div><dt>状态更新时间</dt><dd>{{ time(runtime.storageStateUpdatedTime || runtime.updatedTime) }}</dd></div></dl><p :class="{ 'runtime-warning': runtime.isolationStatus === 'CONFLICT' }">{{ runtime.isolationMessage || '隔离证据尚未生成' }}。这里只展示不可逆摘要，不返回 Cookie、Token 或浏览器存储内容。</p></section>
          <section class="profile-card"><header><strong>数据证据</strong><small>未知不代表 0</small></header><div class="dataset-evidence"><article v-for="(dataset, key) in datasets" :key="key"><div><strong>{{ key === 'shopProfile' ? '店铺画像' : '处罚与风险' }}</strong><span :class="['badge', `badge--${tone(String(dataset.coverageStatus))}`]">{{ statusLabel(String(dataset.coverageStatus)) }}</span></div><p>来源 {{ dataset.source || 'NONE' }} · {{ statusLabel(String(dataset.syncStatus)) }}</p><small>最近成功 {{ time(dataset.lastSuccessTime || dataset.asOfTime) }}</small><em v-if="dataset.lastErrorMessage">{{ dataset.lastErrorMessage }}</em></article><p v-if="!Object.keys(datasets).length" class="profile-empty">数据集同步证据尚未建立。</p></div></section>
        </div>
        <div class="account-profile__right">
          <section class="risk-overview"><header><strong>闲鱼安全处置消息</strong><div><small>上次同步 {{ time(account.riskSyncedAt) }}</small><button :disabled="loading" @click="$emit('refresh')">↻ 刷新</button></div></header><div><span>已知记录总数<strong>{{ account.riskCoverageStatus === 'UNSYNCED' ? '—' : risks.length }}</strong></span><span>当前生效<strong class="warn-text">{{ account.riskCoverageStatus === 'UNSYNCED' ? '—' : activeRisks.length }}</strong></span><span>严重处罚<strong class="bad-text">{{ account.riskCoverageStatus === 'UNSYNCED' ? '—' : severeRisks.length }}</strong></span></div></section>
          <section class="risk-records"><header><div><h3>处罚与风险记录</h3><span>{{ account.riskCoverageStatus === 'UNSYNCED' ? '未同步' : risks.length }}</span></div><small>只读快照 · 按时间倒序</small></header><div class="risk-tabs" role="tablist" aria-label="风险记录筛选"><button :class="{active:riskFilter==='ALL'}" role="tab" :aria-selected="riskFilter==='ALL'" @click="riskFilter='ALL'">全部</button><button :class="{active:riskFilter==='ACTIVE'}" role="tab" :aria-selected="riskFilter==='ACTIVE'" @click="riskFilter='ACTIVE'">生效中</button><button :class="{active:riskFilter==='APPEALING'}" role="tab" :aria-selected="riskFilter==='APPEALING'" @click="riskFilter='APPEALING'">申诉中</button><button :class="{active:riskFilter==='RESOLVED'}" role="tab" :aria-selected="riskFilter==='RESOLVED'" @click="riskFilter='RESOLVED'">已处理</button></div><div v-if="filteredRisks.length" class="risk-items"><article v-for="(risk, index) in filteredRisks" :key="index" :class="`risk-item--${tone(String(risk.severity))}`"><header><div><span :class="['badge', `badge--${tone(String(risk.severity))}`]">{{ statusLabel(String(risk.severity)) }}</span><span :class="['badge', `badge--${tone(String(risk.riskStatus))}`]">{{ statusLabel(String(risk.riskStatus)) }}</span><strong>{{ risk.riskName || '未命名风险' }}</strong></div><code>{{ risk.riskId || risk.ruleCode || '规则编号未同步' }}</code></header><p>{{ risk.impactSummary || '平台影响说明尚未同步。' }}</p><details><summary>运营建议</summary><p>{{ risk.recommendedAction || risk.operationAdvice || '暂无建议动作，请先核对平台原始通知。' }}</p></details><footer>处置于 {{ time(String(risk.punishedTime || risk.effectiveTime || '')) }} <b>{{ risk.appealDeadline ? `申诉截止 ${time(String(risk.appealDeadline))}` : '申诉期限未同步' }}</b></footer></article></div><div v-else class="profile-empty profile-empty--large"><strong>{{ account.riskCoverageStatus === 'UNSYNCED' ? '风险数据尚未同步' : riskFilter === 'ALL' ? '已同步范围内暂无风险记录' : '当前筛选下没有风险记录' }}</strong><p>{{ account.riskCoverageStatus === 'UNSYNCED' ? '不能据此判断为零风险，请先刷新店铺详情。' : '后续风险变化会继续保留来源和同步时间。' }}</p></div></section>
        </div>
      </div>
      <footer class="account-profile__footer"><div><span>● 处罚消息实时推送：待平台支持</span><i></i><span>画像更新于 {{ time(account.profileSyncedAt) }}</span><i></i><kbd>ESC</kbd><span>关闭</span></div><div><button class="workbench__btn" @click="$emit('edit')">编辑账号备注</button><button class="workbench__btn" @click="$emit('close')">关闭</button><button class="workbench__btn workbench__btn--primary" @click="$emit('manage')">管理连接</button></div></footer>
    </section>
  </div>
</template>

